use vstd::prelude::*;

verus! {

    // Specification for the flipud function
    fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
        requires
            // The input vector can be of any length, including empty
            true,
        ensures
            // The result vector has the same length as the input vector
            result.len() == m.len() &&
            // For every valid index i, the element at index i of the result
            // is equal to the element at index (n - 1 - i) of the input
            forall|i: nat| (i < m.len() as nat) ==> (result[i] == m[(m.len() as nat - 1 - i)])
    {
        let n = m.len() as nat;
        let mut result: Vec<f32> = vec![0.0; m.len()]; // Initialize result vector with the same length

        let mut idx: nat = 0; // Index for the result vector
        while idx < n
            invariant
                idx <= n,
                result.len() == m.len(),
                forall|i: nat| (i < idx) ==> (result[i] == m[(n - 1 - i)]),
            decreases n - idx,
        {
            result[idx] = m[(n - 1 - idx)]; // Fill the result vector
            idx = idx + 1; // Move to the next index
        }
        result
    }
}

